#!/usr/bin/env python3
"""Generates the 'unrolled' benchmark classes: InlineN (B) and HybridN (C_stable, 90 % inline + 10 % hooks)."""
import os
OUT = os.path.join(os.path.dirname(__file__), "..", "src/main/java/sk/add/bench/generated")
os.makedirs(OUT, exist_ok=True)
thr = lambda i: (i * 7919) % 1000 + 1   # must match BenchFactory.threshold

def ifs(a, b):
    return "".join(f"        if (q > {thr(i)}) p *= 0.9999;\n" for i in range(a, b))

for n in (4, 10, 100, 1000):
    open(f"{OUT}/Inline{n}.java", "w").write(f"""package sk.add.bench.generated;

import sk.add.domain.*;

/** GENERATED by tools/gen_inline.py - B with {n} inline rules. */
public final class Inline{n} implements PriceCalculator {{
    @Override
    public double calculate(Order o) {{
        double p = o.base();
        int q = o.quantity();
{ifs(0, n)}        return Money.round(p);
    }}
}}
""")
    m = int(0.9 * n)
    open(f"{OUT}/Hybrid{n}.java", "w").write(f"""package sk.add.bench.generated;

import sk.add.a.PricingRule;
import sk.add.bench.BenchFactory;
import sk.add.domain.*;

/** GENERATED by tools/gen_inline.py - C with {m} inline rules + {n - m} through the extension point. */
public final class Hybrid{n} implements PriceCalculator {{
    private final PricingRule[] hooks = BenchFactory.rules({m}, {n}, 1);

    @Override
    public double calculate(Order o) {{
        double p = o.base();
        int q = o.quantity();
{ifs(0, m)}        for (PricingRule h : hooks) p = h.apply(o, p);
        return Money.round(p);
    }}
}}
""")
print("generated")
